previewCss:
.darma-loader-darma-b9-ping-pong { --accent: var(--loader-color, #e2e8f0); --accent-2: var(--loader-secondary-color, #facc15); width: var(--loader-size, 96px); height: calc(var(--loader-size, 96px) * .5); position: relative; }
.darma-loader-darma-b9-ping-pong::before, .darma-loader-darma-b9-ping-pong::after { content: ''; position: absolute; top: 50%; width: calc(var(--loader-size, 96px) * .06); height: 56%; margin-top: -28%; border-radius: calc(var(--loader-size, 96px) * .03); background: var(--accent); }
.darma-loader-darma-b9-ping-pong::before { left: 0; animation: darma-loader-darma-b9-ping-pong-paddle-l calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-darma-b9-ping-pong::after { right: 0; animation: darma-loader-darma-b9-ping-pong-paddle-r calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-darma-b9-ping-pong span { position: absolute; top: 50%; left: 10%; width: calc(var(--loader-size, 96px) * .1); height: calc(var(--loader-size, 96px) * .1); margin-top: calc(var(--loader-size, 96px) * -.05); border-radius: 50%; background: var(--accent-2); animation: darma-loader-darma-b9-ping-pong-ball calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
@keyframes darma-loader-darma-b9-ping-pong-ball { 0%, 100% { left: 10%; top: 30%; } 50% { left: 78%; top: 60%; } }
@keyframes darma-loader-darma-b9-ping-pong-paddle-l { 0%, 100% { transform: translateY(-18%); } 50% { transform: translateY(14%); } }
@keyframes darma-loader-darma-b9-ping-pong-paddle-r { 0%, 100% { transform: translateY(14%); } 50% { transform: translateY(-18%); } }

